// Probe (deleted before delivery): simulate many frames at several frame rates,
// assert the physics never produces NaN, never hangs, and levels advance.
import { createState, step, HEIGHT, WIDTH } from '../game/neon.js';

function simulate(fps, frames) {
  const state = createState(1);
  const dt = 1 / fps;
  let lost = 0;
  let cleared = 0;
  let maxSpeed = 0;
  for (let i = 0; i < frames; i++) {
    // deterministic paddle sweep
    const t = i % 600;
    state.paddle.x = t < 300 ? t * (WIDTH - 96) / 300 : (600 - t) * (WIDTH - 96) / 300;
    const s = step(state, dt);
    maxSpeed = Math.max(maxSpeed, Math.hypot(state.ball.vx, state.ball.vy));
    if (!Number.isFinite(state.ball.x) || !Number.isFinite(state.ball.y) ||
        !Number.isFinite(state.ball.vx) || !Number.isFinite(state.ball.vy)) {
      throw new Error(`NaN at frame ${i}: ${JSON.stringify(state.ball)}`);
    }
    if (state.ball.x - state.ball.r < -1 || state.ball.x + state.ball.r > WIDTH + 1) {
      throw new Error(`ball out of horizontal bounds at frame ${i}`);
    }
    if (s) { lost++; state.ball = createState(state.level).ball; }
    if (state.bricks.every((b) => !b.alive)) {
      cleared++;
      state.level += 1;
      state.bricks = (await import('../game/neon.js')).makeBricks(state.level);
      state.ball = createState(state.level).ball;
    }
  }
  return { lost, cleared, level: state.level, maxSpeed };
}

for (const fps of [144, 60, 30, 20]) {
  const r = simulate(fps, 6000);
  console.log(`${fps} fps: lost=${r.lost} cleared=${r.cleared} level=${r.level} maxSpeed=${r.maxSpeed.toFixed(1)}`);
}
console.log('probe OK');

