// Probe v2: trace the first frames to see where the ball goes.
import { createState, step, makeBricks, HEIGHT, WIDTH } from '../game/neon.js';

const state = createState(1);
const dt = 1 / 60;
let destroyed = 0;
let prevBricks = state.bricks.filter((b) => b.alive).length;
let lost = 0;
for (let i = 0; i < 900; i++) {
  if (state.ball.vy > 0 && state.ball.y > HEIGHT - 200) {
    const target = Math.max(0, Math.min(WIDTH - 96, state.ball.x - 48));
    state.paddle.x = state.paddle.x + Math.max(-8, Math.min(8, target - state.paddle.x));
  }
  const s = step(state, dt);
  const alive = state.bricks.filter((b) => b.alive).length;
  if (alive < prevBricks) {
    destroyed += prevBricks - alive;
