// Probe 3: last-brick scenario — brick dies in step(), level must advance the
// same frame (no life lost on a cleared level).
import { createState, step, makeBricks, HEIGHT } from '../game/neon.js';

const state = createState(1);
state.ball = { x: 136, y: 92, r: 7, vx: 0, vy: 260 }; // descending onto the last brick
state.bricks = [{ x: 100, y: 100, w: 72, h: 20, row: 4, alive: true, points: 10 }];
state.lives = 3;

const lost = step(state, 1 / 60);
const cleared = state.bricks.every((b) => !b.alive);
console.log(`lost=${lost} cleared=${cleared} lives=${state.lives} score=${state.score}`);
if (cleared) {
  // replicate the loop() level-advance branch
  state.level += 1;
  state.bricks = makeBricks(state.level);
  state.ball = createState(state.level).ball;
  console.log(`advanced to level ${state.level}, ${state.bricks.filter((b) => b.alive).length} bricks`);
}
if (lost) throw new Error('life lost on a cleared level');
if (!cleared) throw new Error('level not cleared');
console.log('probe3 OK');

