// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Sub-step length (seconds). The frame step `dt` is split into sub-steps short
// enough that the ball can never jump over an obstacle in one hop: at the
// fastest level speed (≈ 1970 px/s) a 4 ms sub-step moves the ball ≈ 7.9 px,
// below the thinnest obstacle (paddle, 12 px) and below the brick skip window
// (BRICK_H + 2·BALL_R = 34 px). This is the swept guarantee: the same
// collision happens whatever the frame rate.
const SUB_STEP = 0.004;

// Minimum |hit| on the paddle. A hit exactly at the paddle center gives
// hit = 0, hence vx = 0 and a dead vertical loop; clamping the hit to at
// least PADDLE_MIN_HIT keeps every trajectory playable while the speed is
// still normalized below.
const PADDLE_MIN_HIT = 0.25;

// Upper bound for the brick-resolution loop. Each pass resolves the closest
// overlapping brick and pushes the ball out; bricks do not move, so the loop
// converges after as many passes as there were overlapping bricks.
const BRICK_RESOLVE_PASSES = 8;

// True if the ball's box overlaps the rectangle (used for the paddle, which
// must catch the ball by its box — the old center-only test let balls slip
// through the paddle corners).
function boxOverlap(ball, rect) {
  return (
    ball.x + ball.r > rect.x &&
    ball.x - ball.r < rect.x + rect.w &&
    ball.y + ball.r > rect.y &&
    ball.y - ball.r < rect.y + rect.h
  );
}

// Brick collision resolution: every alive brick overlapped by the ball is
// broken (combo + score), and the ball is bounced **once per axis** off the
// group. The axis chosen is the one with the smallest penetration; on equal
// penetration we are on a corner and BOTH axes flip. The ball is always
// pushed fully out of the brick through the face it entered, so the overlap
// never survives to the next sub-step (no stick, no double inversion).
function resolveBricks(state) {
  const { ball } = state;

  for (let pass = 0; pass < BRICK_RESOLVE_PASSES; pass++) {
    let minPenX = Infinity;
    let minPenY = Infinity;
    let dirX = 0; // -1: entered from the left (push left), +1: push right
    let dirY = 0; // -1: entered from above (push up),  +1: push down
    let hitBrickX = null; // brick giving the smallest x penetration
    let hitBrickY = null; // brick giving the smallest y penetration
    let hitAny = false;

    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (!collides(ball, brick)) continue;

      brick.alive = false;
      hitAny = true;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      const penX = Math.min(
        ball.x + ball.r - brick.x,
        brick.x + brick.w - (ball.x - ball.r)
      );
      const penY = Math.min(
        ball.y + ball.r - brick.y,
        brick.y + brick.h - (ball.y - ball.r)
      );
      if (penX < minPenX) {
        minPenX = penX;
        dirX = ball.x + ball.r - brick.x < brick.x + brick.w - (ball.x - ball.r) ? -1 : 1;
        hitBrickX = brick;
      }
      if (penY < minPenY) {
        minPenY = penY;
        dirY = ball.y + ball.r - brick.y < brick.y + brick.h - (ball.y - ball.r) ? -1 : 1;
        hitBrickY = brick;
      }
    }

    if (!hitAny) return;

    const corner = minPenX === minPenY;
    const flipX = corner || minPenX < minPenY;
    const flipY = corner || minPenY < minPenX;

    // Flip an axis only if the ball was moving INTO the brick on it; a ball
    // already leaving the brick must not be re-flipped by a later pass.
    if (flipX && Math.sign(ball.vx) === -dirX) ball.vx = -ball.vx;
    if (flipY && Math.sign(ball.vy) === -dirY) ball.vy = -ball.vy;

    // Push the ball fully out through the face it entered.
    if (flipX) ball.x = dirX < 0 ? hitBrickX.x - ball.r : hitBrickX.x + hitBrickX.w + ball.r;
    if (flipY) ball.y = dirY < 0 ? hitBrickY.y - ball.r : hitBrickY.y + hitBrickY.h + ball.r;
  }
}

